void flag(SessionEntry& e,const CombatContent& c,int id,bool on){e.worldFlags[c.facts.switches.at(id)]=on;e.flags.erase(id);}
CombatEntry entry(const CombatContent& c,const SessionEntry& base,int map,TilePosition tile){auto e=c.entries.at("post-pickup");e.map=map;e.playerTile=tile;e.direction=Direction::Up;e.session=base;e.session.flags[1]=true;e.session.flags[18]=true;e.session.flags[10]=false;e.session.flags[13]=false;e.session.hp=100;e.session.conditions={};e.positions.clear();e.directions.clear();e.pages.clear();e.through.clear();return e;}
void settle(CombatScene& scene){for(int n=0;n<4000;++n){if(scene.foreground()==ForegroundKind::None&&!scene.dialogue().active()){return;}scene.update(n%8==0?key():InputFrame{});scene.takePresentation();}throw std::runtime_error("G6 fixture flow stalled");}
EnemyView enemy(const CombatScene& s,const std::string& id){for(const auto& e:s.enemyStates()){if(e.id==id){return e;}}throw std::runtime_error("Missing G6 enemy "+id);}
AttackResolution hit(CombatScene& scene,const std::string& id,int receiver){const auto p=findCharacter(scene.world(),id).motion.position();std::set<std::string> ids;return scene.resolveAttack({{(p.x+.5)*16,(p.y+.5)*16},{0,0},AttackKind::Handgun,receiver,0,false},ids);}
